class Solution {
    public int closestTriple(int[] values, int target) {
        int n = values.length, best = values[0] + values[1] + values[2];
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                for (int k = j + 1; k < n; k++) {
                    int s = values[i] + values[j] + values[k];
                    int d = Math.abs(s - target), bd = Math.abs(best - target);
                    if (d < bd || (d == bd && s < best)) best = s;
                }
        return best;
    }
}

