class Solution:
    def closestTriple(self, values: List[int], target: int) -> int:
        a = sorted(values)
        best = a[0] + a[1] + a[2]
        for i in range(len(a) - 2):
            j, k = i + 1, len(a) - 1
            while j < k:
                s = a[i] + a[j] + a[k]
                if (abs(s - target), s) < (abs(best - target), best):
                    best = s
                if s < target:
                    j += 1
                elif s > target:
                    k -= 1
                else:
                    return s
        return best

