class Solution {
    public int closestTriple(int[] values, int target) {
        int[] a = values.clone();
        Arrays.sort(a);
        int best = a[0] + a[1] + a[2];
        for (int i = 0; i + 2 < a.length; i++) {
            int j = i + 1, k = a.length - 1;
            while (j < k) {
                int s = a[i] + a[j] + a[k];
                int d = Math.abs(s - target), bd = Math.abs(best - target);
                if (d < bd || (d == bd && s < best)) best = s;
                if (s < target) j++;
                else if (s > target) k--;
                else return s;
            }
        }
        return best;
    }
}

