static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

int closestTriple(int* values, int valuesSize, int target) {
    int n = valuesSize;
    int* a = malloc(n * sizeof(int));
    memcpy(a, values, n * sizeof(int));
    qsort(a, n, sizeof(int), cmp_int);
    int best = a[0] + a[1] + a[2];
    for (int i = 0; i + 2 < n && best != target; i++) {
        int j = i + 1, k = n - 1;
        while (j < k) {
            int s = a[i] + a[j] + a[k];
            int d = abs(s - target), bd = abs(best - target);
            if (d < bd || (d == bd && s < best)) best = s;
            if (s < target) j++;
            else if (s > target) k--;
            else break;
        }
    }
    free(a);
    return best;
}
